60	const VOR_BETRIEB = ["interesse", "machbarkeit", "in_gruendung", "rechtsperson", "marktpartner", "vertrag_nb", "eda_bereit"];
61	
62	const tag = (v) => String(v || "").slice(0, 10);
63	/** Organ am Stichtag wirksam? */
64	export function organWirksam(o, heute) {
65	  if (!o || o.status === "beendet") return false;
66	  const h = tag(heute);
67	  return (!o.von || tag(o.von) <= h) && (!o.bis || tag(o.bis) >= h);
68	}
