70	/**
71	 * Kontext-Rollen eines Kontos in einer Gemeinschaft.
72	 * @param {{nutzer:object, gemeinschaft:object, organe?:object[], mitglieder?:object[], heute:string}} k
73	 * @returns {{rollen:string[], backofficeStufe:number}}
74	 */
75	export function egRollen({ nutzer, gemeinschaft, organe = [], mitglieder = [], heute } = {}) {
76	  const rollen = new Set();
77	  let backofficeStufe = 0;
78	  if (!nutzer || !gemeinschaft) return { rollen: [], backofficeStufe };
79	  const gid = gemeinschaft.id;
80	  for (const o of organe) {
81	    if (o.gemeinschaftId === gid && o.kontoId && o.kontoId === nutzer.id && organWirksam(o, heute)) {
82	      const r = ORGAN_FUNKTIONEN[o.funktion]?.teamrolle;
83	      if (r) rollen.add(r);
84	    }
85	  }
86	  for (const m of mitglieder) {
87	    if (m.gemeinschaftId !== gid || !m.kontoId || m.kontoId !== nutzer.id) continue;
88	    if (MITGLIED_AKTIV.includes(m.status)) rollen.add(m.art === "gemeinde" ? "gemeinde" : "mitglied");
89	    else if (["interessent", "antrag", "geprueft"].includes(m.status)) rollen.add("interessent");
90	  }
91	  if (nutzer.rollen?.includes("admin") && darfLesen(nutzer, "eg")) {
92	    backofficeStufe = darfSchreiben(nutzer, "eg") ? 2 : 1;
93	    if (VOR_BETRIEB.includes(gemeinschaft.status) || !GEMEINSCHAFT_STATUS[gemeinschaft.status]) rollen.add("gruendung");
94	    if (gemeinschaft.dienstleistung?.aktiv) rollen.add("organisator");
95	  }
96	  return { rollen: R.filter((r) => rollen.has(r)), backofficeStufe };
97	}
