99	/** Stufe (0–2) eines Rollen-Kontexts für ein Recht; Backoffice-Rollen gedeckelt auf die Stufe im Bereich „eg“ */
100	export function egStufe(kontext, recht) {
101	  const z = EG_RECHTE[recht]?.rollen;
102	  if (!z || !kontext) return 0;
103	  const aus = (kontext.rollen || []).reduce((m, r) => Math.max(m, BACKOFFICE_ROLLEN.includes(r) ? Math.min(z[r] || 0, kontext.backofficeStufe || 0) : z[r] || 0), 0);
104	  return BACKOFFICE_PFLEGE.includes(recht) ? Math.max(aus, kontext.backofficeStufe || 0) : aus;
105	}
106	export const egDarf = (kontext, recht, stufe = 1) => egStufe(kontext, recht) >= stufe;
