108	/** Alle Rechte eines Kontexts als { recht: stufe } (für Seiten: Knöpfe ein-/ausblenden – geprüft wird serverseitig) */
109	export const egRechteVon = (kontext) => Object.fromEntries(EG_RECHTE_IDS.map((r) => [r, egStufe(kontext, r)]));
