541	export async function egMassenaktion(n, gemeinschaftId, { aktion = "", ids = [], werte = {} } = {}) {
542	  const def = MASSEN[aktion];
543	  if (!def) throw ungueltig("Unbekannte Massenaktion.");
544	  const liste = [...new Set((Array.isArray(ids) ? ids : []).map(String))].slice(0, 2000);
545	  if (!liste.length) throw ungueltig("Bitte mindestens einen Eintrag auswählen.");
546	  return aendernBereit((db) => {
547	    const { g } = zugriff(db, n, gemeinschaftId, def.recht, 2);
548	    const x = E(db);
549	    const fehler = [];
550	    let anzahl = 0;
551	    for (const id of liste) {
552	      try {
553	        if (["mitglied_status", "rechnungsweg", "abrechnungsrhythmus", "schutzbeduerftig"].includes(aktion)) {
554	          const m = x.mitglieder.find((y) => y.id === id && y.gemeinschaftId === g.id);
555	          if (!m) throw ungueltig("nicht gefunden");
556	          if (aktion === "mitglied_status") Object.assign(m, fach(() => mitgliedUebergang(m, werte.nach, { grund: werte.grund, zum: werte.zum })));
557	          if (aktion === "rechnungsweg") { if (!RECHNUNGSWEGE[werte.wert]) throw ungueltig("Rechnungsweg ungültig"); m.rechnungsweg = werte.wert; }
558	          if (aktion === "abrechnungsrhythmus") { if (werte.wert && !ABRECHNUNGSRHYTHMEN[werte.wert]) throw ungueltig("Rhythmus ungültig"); m.abrechnungsrhythmus = werte.wert || ""; }
559	          if (aktion === "schutzbeduerftig") m.schutzbeduerftig = werte.wert === true;
560	          geaendert(m, n);
561	        } else if (["zp_smartmeter", "zp_netzebene"].includes(aktion)) {
562	          const z = x.zaehlpunkte.find((y) => y.id === id && x.teilnahmen.some((t) => t.zaehlpunktId === y.id && t.gemeinschaftId === g.id));
563	          if (!z) throw ungueltig("nicht gefunden");
564	          if (aktion === "zp_smartmeter") { if (!SMART_METER[werte.wert]) throw ungueltig("Wert ungültig"); z.smartMeter = werte.wert; }
565	          if (aktion === "zp_netzebene") { if (!NETZEBENEN[Number(werte.wert)]) throw ungueltig("Netzebene ungültig"); z.netzebene = Number(werte.wert); }
566	          geaendert(z, n);
567	        } else {
568	          const t = x.teilnahmen.find((y) => y.id === id && y.gemeinschaftId === g.id);
569	          if (!t) throw ungueltig("nicht gefunden");
570	          if (t.status !== "entwurf") throw konflikt("nur Entwürfe");
571	          if (aktion === "tf_entwurf") {
572	            const r = teilnahmeRegeln(x.teilnahmen.filter((y) => y.zaehlpunktId === t.zaehlpunktId), { id: t.id, gemeinschaftId: g.id, teilnahmefaktor: Number(werte.teilnahmefaktor) });
573	            if (!Number.isInteger(Number(werte.teilnahmefaktor)) || Number(werte.teilnahmefaktor) < 1 || Number(werte.teilnahmefaktor) > 100) throw ungueltig("TF 1–100");
574	            if (!r.ok) throw konflikt(r.fehler);
575	            t.teilnahmefaktor = Number(werte.teilnahmefaktor);
576	          } else t.anmeldungVorgemerkt = werte.wert !== false;
577	          geaendert(t, n);
578	        }
579	        anzahl++;
580	      } catch (e) {
581	        fehler.push({ id, fehler: e.message });
582	      }
583	    }
584	    protokoll(db, n, "eg_massenaktion", "eg_gemeinschaft", g.id, `Massenaktion ${def.text}: ${anzahl} geändert, ${fehler.length} Fehler`);
585	    return { geaendert: anzahl, fehler };
586	  });
