  const ich = s.unterzeichner.find((u) => u.kontoId === n.id) || null;
  const basis = {
    id: s.id, titel: s.titel, art: s.art, artLabel: SIGNATUR_ARTEN[s.art]?.label || s.art, status, statusLabel: SIGNATUR_STATUS[status]?.label || status,
