/** Cent je kWh mit 2–4 Nachkommastellen (Tarife bis 4 NK, Fachkonzept 3.10) */
const ctDe = (x) => {
  if (leer(x) || !Number.isFinite(Number(x))) return "";
  const [g, k] = zahlDe(x, 4).split(",");
  let n = k;
  while (n.length > 2 && n.endsWith("0")) n = n.slice(0, -1);
  return `${g},${n} ct/kWh`;
};

