  if (g.modell === "eeg") f("info", "EEG: Zweck „Hauptzweck nicht finanzieller Gewinn“, offener und freiwilliger Mitgliederkreis ohne Großunternehmen sind enthalten.", "EAG § 79 Abs. 2; ElWG § 66");
