// /api/portal/eg/gruendung – Gründungsaufträge (WP5)
//   GET  ?status=&paket=&q=   eigene Aufträge (Auftraggeber bzw. Organe der Gemeinschaft); Backoffice (Bereich „eg“): alle mit Kennzahlen
//   POST { daten: { paket, arbeitsname, modell, zonelevel?, rechtsform?, plz, ort, bundesland?, netzbetreiberId?, erwarteteMitglieder?, erzeugungKwp?,
//          speicherKwh?, gemeindeBeteiligt?, investitionGeplant?, bestehend? (Wechsel), ansprechpartner?, nachricht?, einwilligung } }
// Rechte prüft das Backend (backend/eg.js → grAuftraege/grAuftragAnlegen).
import { route } from "@/lib/plattform/server/route";
import { grenze, rateLimit } from "@/lib/plattform/server/rateLimit";
import { egBackend } from "@/lib/plattform/backend/eg";

export const GET = route({}, async ({ nutzer, suche }) => ({ ok: true, ...(await egBackend().grAuftraege(nutzer, { status: suche.get("status") || "", paket: suche.get("paket") || "", q: suche.get("q") || "" })) }));

export const POST = route({}, async ({ nutzer, body }) => {
  rateLimit(`eg-gruendung:${nutzer.id}`, ...grenze("anfrage"));
  return Response.json({ ok: true, auftrag: await egBackend().grAuftragAnlegen(nutzer, { daten: body?.daten || {} }) }, { status: 201, headers: { "Cache-Control": "no-store" } });
});
EOF
cat > "gruendung/[id]/route.js" <<'EOF'
// /api/portal/eg/gruendung/[id] – Gründungsauftrag (WP5)
//   GET   Detail mit Schritten, Fristen, Formularhilfen, Dokumenten, Importen, Förder-Checks
//   POST  { aktion: angebot | signatur | annehmen | ablehnen | beauftragt_manuell | gemeinschaft_anlegen | gemeinschaft_verknuepfen | daten |
//           schritte_aktualisieren | stichtag | statuten | notiz | abbrechen | uebergeben | probeabrechnung | mitglieder_informieren, … }
import { route } from "@/lib/plattform/server/route";
import { egBackend } from "@/lib/plattform/backend/eg";

export const GET = route({}, async ({ nutzer, params }) => ({ ok: true, auftrag: await egBackend().grAuftrag(nutzer, params.id) }));

export const POST = route({ maxBytes: 1024 * 1024 }, async ({ nutzer, params, body }) => ({ ok: true, auftrag: await egBackend().grAuftragAktion(nutzer, params.id, body || {}) }));
EOF
cat > "gruendung/[id]/schritt/route.js" <<'EOF'
// POST /api/portal/eg/gruendung/[id]/schritt – { schritt, aktion: starten | warten | erledigen | entfaellt | wiedereroeffnen | frist | notiz,
//   datum?, wert?, notiz?, frist?, grund?, nachweis?: { titel, dokumentId } } (WP5). Wirkung auf die Gemeinschaft läuft über WP1.
import { route } from "@/lib/plattform/server/route";
import { egBackend } from "@/lib/plattform/backend/eg";

export const POST = route({}, async ({ nutzer, params, body }) => ({ ok: true, auftrag: await egBackend().grSchrittAktion(nutzer, params.id, body || {}) }));
EOF
cat > dokument/route.js <<'EOF'
// /api/portal/eg/dokument – Dokumentgenerator (WP5): Musterstatuten, Verträge, Vollmachten, Anzeigen, Mitgliederinformationen
//   GET  ?id=EGD-…                                     gespeicherte Version als PDF
//   GET  ?vorlage=…&gemeinschaftId=…|auftragId=…        Vorschau als PDF (ohne Speichern; Eingaben aus der Vorlage)
//   POST { vorlage, gemeinschaftId? | auftragId?, daten?, speichern? }  → { dokument (Version, SHA-256), pruefung }
// Jedes Dokument ist ein MUSTER zur rechtlichen Prüfung (Rechtsstand ElWG 01.10.2026).
import { route } from "@/lib/plattform/server/route";
import { egBackend } from "@/lib/plattform/backend/eg";
import { egDokumentPdf, pdfDateiname } from "@/lib/plattform/server/eg-gruendung-pdf";

const pdfAntwort = (r) =>
  new Response(egDokumentPdf(r.dok, { version: r.dokument.version || "Vorschau", sha256: r.dokument.sha256, demo: !!r.dokument.demo }), {
    headers: { "Content-Type": "application/pdf", "Content-Disposition": `inline; filename="${pdfDateiname(`${r.dok.titel}${r.dokument.version ? `-v${r.dokument.version}` : "-vorschau"}`)}"`, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff" },
  });

export const GET = route({}, async ({ nutzer, suche }) => {
  const b = egBackend();
  const id = suche.get("id") || "";
  if (id) return pdfAntwort(await b.grDokumentErzeugen(nutzer, { dokumentId: id }));
  return pdfAntwort(await b.grDokumentErzeugen(nutzer, { vorlage: suche.get("vorlage") || "", gemeinschaftId: suche.get("gemeinschaftId") || "", auftragId: suche.get("auftragId") || "", speichern: false }));
});

export const POST = route({}, async ({ nutzer, body }) => {
  const r = await egBackend().grDokumentErzeugen(nutzer, { vorlage: body?.vorlage || "", gemeinschaftId: body?.gemeinschaftId || "", auftragId: body?.auftragId || "", daten: body?.daten || {}, speichern: body?.speichern !== false });
  return { ok: true, dokument: r.dokument, pruefung: r.pruefung, fehlend: r.dok?.fehlend || [], pflichtFehlend: r.dok?.pflichtFehlend || [], unveraendert: !!r.unveraendert };
});
EOF
cat > foerdercheck/route.js <<'EOF'
// POST /api/portal/eg/foerdercheck – Förder-Check (WP5) { gemeinschaftId?, auftragId?, daten: { modell, bundesland, antragsteller,
//   gemeindeBeteiligt, anlagen[{art, kwp, speicherKwh, status, bezeichnung}] }, speichern? } → Programme mit Ergebnis, Gründen, Quellen
