// /portal/admin/eg – Backoffice (Bereich „eg“): alle Energiegemeinschaften mit Kennzahlen, Filter nach Status und Modell,
// Hinweise (§ 69, Organisator-Anzeige, Gemeinschafts-ID …), neue Gemeinschaft, Migration aus dem Prototyp. WP1.

import Link from "next/link";
import { Building2, Gauge, PlugZap, Sun, TriangleAlert, Users } from "lucide-react";
import { Badge, Hinweis, Karte, Kennzahl, Leer, SeitenKopf, Tabelle, zelle } from "@/components/Portal/ui";
import { Klappe } from "@/components/Portal/Mitglied/teile";
import { GemeinschaftNeu, MigrationPrototyp } from "@/components/Portal/EG/Stamm/Formulare";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";
import { EG_MODELLE, GEMEINSCHAFT_STATUS } from "@/lib/plattform/eg/modell";

export const metadata = { title: "Energiegemeinschaften" };
const zahl = (x, s = 0) => Number(x || 0).toLocaleString("de-DE", { maximumFractionDigits: s });

export default async function EgListe({ searchParams }) {
  const n = await portalNutzer({ admin: true });
  const sp = (await searchParams) || {};
  const status = GEMEINSCHAFT_STATUS[sp.status] ? sp.status : "";
  const modell = EG_MODELLE[sp.modell] ? sp.modell : "";
  const q = typeof sp.q === "string" ? sp.q.slice(0, 80) : "";
  const b = egBackend();
  const [d, nb] = await Promise.all([laden(() => b.egGemeinschaften(n, { status, modell, q })), laden(() => b.egNetzbetreiber(n))]);
  const k = d.kennzahlen;
  const link = (p) => {
    const u = new URLSearchParams(Object.entries({ status, modell, q, ...p }).filter(([, v]) => v));
    return `/portal/admin/eg${u.toString() ? `?${u}` : ""}`;
  };
  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow="Backoffice" titel="Energiegemeinschaften" text="EEG, BEG, GEA, P2P und Eigenversorgung nach ElWG: Stammdaten, Organe, Mitglieder, Zählpunkte und Teilnahmen aller betreuten Gemeinschaften." aktionen={<Link href="/portal/admin/eg/netzbetreiber" className="text-[14px] font-semibold text-ov-700 hover:text-ov-800">Netzbetreiber & Netzentgelte</Link>} />
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kennzahl label="Gemeinschaften" wert={zahl(k.anzahl)} hinweis={`${k.aktiv} aktiv · ${k.inGruendung} in Gründung`} icon={Building2} />
        <Kennzahl label="Aktive Mitglieder" wert={zahl(k.mitgliederAktiv)} icon={Users} />
        <Kennzahl label="Aktive Zählpunkte" wert={zahl(k.zaehlpunkteAktiv)} hinweis={`${k.teilnahmenOffen} Anmeldungen offen`} icon={PlugZap} />
        <Kennzahl label="Erzeugungsleistung" wert={`${zahl(k.erzeugungsleistungKw, 1)} kW`} hinweis={`${k.mitHinweisen} Gemeinschaft(en) mit Handlungsbedarf`} icon={Sun} />
      </div>

      <Karte titel="Übersicht" aktion={<Gauge aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
        <form action="/portal/admin/eg" className="mb-4 flex flex-wrap gap-2" role="search">
// /portal/eg – Energiegemeinschaft im Portal (WP6): eigene Mitgliedschaften mit Status Schritt für Schritt, offene
// Aufgaben (Zustimmung beim Netzbetreiber mit Frist), Mehrfachteilnahme, Einstieg für Organe (WP1-Verwaltung) und Gemeinden,
// für Interessenten die Gemeinschaftssuche mit Eignungscheck. Nur eigene Daten (ptUebersicht).

import Link from "next/link";
import { ArrowRight, Building2, Calculator, FileJson, Landmark, Search, SlidersHorizontal, SunMedium, Users } from "lucide-react";
import { Badge, Karte, PfeilLink, SeitenKopf } from "@/components/Portal/ui";
import { TfBalken, ZustimmungJetzt } from "@/components/Portal/EG/Mitglied/Teile";
import GemeinschaftFinden from "@/components/Portal/EG/Mitglied/GemeinschaftFinden";
import { ct, datumDe, zpKurz } from "@/components/Portal/EG/Mitglied/format";
import { portalNutzer } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";
import { GEMEINSCHAFT_STATUS, MITGLIED_STATUS } from "@/lib/plattform/eg/modell";

/** Download (API, kein Client-Routing) */
const AUSKUNFT = "/api/portal/eg/datenauskunft?download=1";

export const metadata = { title: "Energiegemeinschaft" };

export default async function Seite() {
  const n = await portalNutzer();
  const d = await egBackend().ptUebersicht(n);
  const aktiv = d.mitgliedschaften.filter((m) => m.mitglied.status !== "ausgeschieden");
  const mehrfach = d.mehrfach.filter((z) => z.mehrfach || z.richtung === "erzeugung");
  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Mein Portal"
        titel="Energiegemeinschaft"
        text={aktiv.length ? "Ihr Gemeinschaftsstrom, Ihre Zählpunkte und alles, was als Nächstes zu tun ist – an einem Ort." : "Strom aus Anlagen in Ihrer Nähe beziehen oder Ihren Überschuss an Nachbarn weitergeben: Finden Sie eine passende Gemeinschaft."}

input.content:
// /portal/eg/gruendung – Gemeinschaft gründen bzw. zu ÖkoInvest wechseln (WP5, Auftraggeber): eigene Gründungsaufträge
// mit Fortschritt und nächsten Fristen, Pakete, Förder-Check. Rechte: angemeldet; sichtbar sind nur eigene Aufträge bzw. die
// der Gemeinschaften, in denen das Konto Vorstand ist (grAuftraege).

import Link from "next/link";
import { ArrowRight, ClipboardList, HandCoins, Repeat, Rocket } from "lucide-react";
import { Badge, Karte, Leer, PfeilLink, QualitaetsBalken, SeitenKopf } from "@/components/Portal/ui";
import { FristBadge, datumDe, eurDe } from "@/components/Portal/EG/Gruendung/teile";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";
import { GR_PAKETE } from "@/lib/plattform/eg/gruendung";

export const metadata = { title: "Gemeinschaft gründen" };
const ICON = { check: ClipboardList, gruendung: Rocket, komplett: Rocket, wechsel: Repeat };

export default async function Seite() {
  const n = await portalNutzer();
  const d = await laden(() => egBackend().grAuftraege(n, {}));
  return (
    <div className="space-y-6">
      <SeitenKopf
        eyebrow="Energiegemeinschaften"
        titel="Gemeinschaft gründen oder wechseln"
        text="Von der Machbarkeit über Statuten, Vereinsbehörde, Finanzamt, Marktpartner und Netzbetreiber bis zur ersten Anmeldung – oder der Wechsel Ihrer bestehenden Gemeinschaft ohne Neuanmeldung der Zählpunkte."
        aktionen={<Link href="/portal/eg/gruendung/neu" className="inline-flex h-11 items-center gap-2 rounded-full bg-ov-600 px-5 text-[14.5px] font-semibold text-white hover:bg-ov-700">Anfrage starten<ArrowRight aria-hidden="true" className="h-4 w-4" /></Link>}
      />
      {d.auftraege.length ? (
        <Karte titel="Ihre Aufträge">
          <ul className="divide-y divide-ink-100">
            {d.auftraege.map((a) => (
              <li key={a.id} className="py-4 first:pt-0 last:pb-0">
                <Link href={`/portal/eg/gruendung/${a.id}`} className="group block">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="font-display text-[16.5px] font-bold text-ink-900 group-hover:text-ov-800">{a.arbeitsname}</p>
                      <p className="text-[13px] text-ink-500">{a.paketLabel} · {a.modellKurz} · {a.plz} {a.ort} · angefragt am {datumDe(a.erstelltAm)}</p>
                    </div>
                    <div className="flex flex-wrap gap-2"><Badge ton={a.ton}>{a.statusLabel}</Badge>{a.angebot && a.status === "angebot" && <Badge ton="info">Angebot {eurDe(a.angebot.betragNetto)} netto</Badge>}</div>
                  </div>
                  {a.auftragAm && <div className="mt-3 max-w-md"><QualitaetsBalken quote={a.fortschritt.prozent} label="Pflichtschritte erledigt" klein /></div>}
                  {a.fortschritt.naechste.length > 0 && a.auftragAm && (
                    <ul className="mt-2 flex flex-wrap gap-2 text-[12.5px] text-ink-600">
                      {a.fortschritt.naechste.map((s) => <li key={s.schluessel} className="flex items-center gap-1.5 rounded-full bg-ink-50 px-2.5 py-1">{s.label}<FristBadge frist={s.frist} ampel={s.ampel} /></li>)}
                    </ul>
                  )}
                </Link>
              </li>
            ))}
          </ul>
        </Karte>
      ) : (
        <Leer icon={Rocket} titel="Noch kein Auftrag" text="Erzählen Sie uns von Ihrer Idee – wir prüfen Netzgebiet, Nahebereich und Wirtschaftlichkeit und machen Ihnen ein Angebot." aktion={<PfeilLink href="/portal/eg/gruendung/neu">Anfrage starten</PfeilLink>} />
      )}
      <div className="grid gap-4 md:grid-cols-2">
        {Object.entries(GR_PAKETE).map(([k, p]) => {
          const I = ICON[k];
          return (
            <Karte key={k} titel={p.label} aktion={<I aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
              <p className="text-[14px] leading-relaxed text-ink-600">{p.text}</p>
