# ================================================================ Statuten (statuten.js)


def _ganz_zahl(v, mn, mx, std):
	n = _js_number(v) if v is not None else float("nan")
	return int(n) if n == n and math.isfinite(n) and float(n).is_integer() and mn <= n <= mx else std


def _stxt(v, mx=300):
	if v is None or isinstance(v, (dict, list)):
		return ""
	return re.sub(r"\s+", " ", _js_str(v)).strip()[:mx]


def statuten_eingaben(d=None):
	d = d or {}
	ga = d.get("geschaeftsanteilEur")
	if ga is None or ga == "":
		ga_s = ""
	else:
		n = _js_number(ga)
		ga_s = _js_str(_ganz_zahl(_js_round(n) if n == n else n, 1, 100000, 100))
	og = d.get("onlineGv")
	return {
		"taetigkeitsgebiet": _stxt(d.get("taetigkeitsgebiet"), 300),
