// src/lib/plattform/backend/frappe/eg-gruendung.js
//
// STUB WP5 „Gründung, Wechsel, Verein, Förder-Check“ (Frappe-Adapter) – angelegt von WP1 als Platzhalter, damit die Fassade
// backend/eg.js vollständig ist. WP5 ersetzt diese Datei vollständig durch die echte Implementierung (gleiche Exporte,
// Signaturen laut docs/EG-SCHNITTSTELLEN.md, Abschnitt 4). Bis dahin antwortet jede Operation mit 501.
// Vorgesehene Frappe-Methoden (oekoinvest_app.plattform.api.eg_gruendung): grAuftraege → eg_gruendung.auftraege, grAuftrag → eg_gruendung.auftrag, grAuftragAnlegen → eg_gruendung.auftrag_anlegen, grAuftragAktion → eg_gruendung.auftrag_aktion, grSchrittAktion → eg_gruendung.schritt_aktion, grDokumentErzeugen → eg_gruendung.dokument_erzeugen, grImportVorschau → eg_gruendung.import_vorschau, grImportAusfuehren → eg_gruendung.import_ausfuehren, grFoerdercheck → eg_gruendung.foerdercheck, grVersammlungen → eg_gruendung.versammlungen, grAufloesung → eg_gruendung.aufloesung.
// Muster: backend/frappe/eg-stamm.js (Object.assign(METHODEN, …) + aufruf).

import { PlattformFehler } from "../../fehler";

const offen = (op) => async () => {
  throw new PlattformFehler(501, `Energiegemeinschaften: „${op}“ ist im Frappe-Backend noch nicht umgesetzt (WP5).`);
};

export const grAuftraege = offen("grAuftraege");
export const grAuftrag = offen("grAuftrag");
export const grAuftragAnlegen = offen("grAuftragAnlegen");
export const grAuftragAktion = offen("grAuftragAktion");
export const grSchrittAktion = offen("grSchrittAktion");
export const grDokumentErzeugen = offen("grDokumentErzeugen");
export const grImportVorschau = offen("grImportVorschau");
export const grImportAusfuehren = offen("grImportAusfuehren");
export const grFoerdercheck = offen("grFoerdercheck");
export const grVersammlungen = offen("grVersammlungen");
export const grAufloesung = offen("grAufloesung");
// src/lib/plattform/backend/frappe/eg-stamm.js
//
// Frappe-Adapter WP1 „Kern-Stammdaten“ des Moduls Energiegemeinschaften. Methoden in oekoinvest_app.plattform.api.eg_stamm –
// Signaturen identisch zu backend/demo/eg-stamm.js (Vertrag: docs/EG-SCHNITTSTELLEN.md). Frappe prüft Rolle, Kontext-Rolle
// je Gemeinschaft (eg_stamm_kern.rollen_von) und Bereich „eg“ der Rechte-Matrix selbst.

import { METHODEN, frappeAufruf as aufruf } from "../frappe";

Object.assign(METHODEN, {
  egKontext: "eg_stamm.kontext",
  egGemeinschaften: "eg_stamm.gemeinschaften",
  egGemeinschaft: "eg_stamm.gemeinschaft",
  egGemeinschaftSpeichern: "eg_stamm.gemeinschaft_speichern",
  egGemeinschaftStatus: "eg_stamm.gemeinschaft_status",
  egOrganSpeichern: "eg_stamm.organ_speichern",
  egOrganBeenden: "eg_stamm.organ_beenden",
  egMitgliedSpeichern: "eg_stamm.mitglied_speichern",
  egMitgliedStatus: "eg_stamm.mitglied_status",
  egZaehlpunktSpeichern: "eg_stamm.zaehlpunkt_speichern",
  egTeilnahmeSpeichern: "eg_stamm.teilnahme_speichern",
  egTeilnahmeUebergang: "eg_stamm.teilnahme_uebergang",
  egAnlageSpeichern: "eg_stamm.anlage_speichern",
  egTarifSpeichern: "eg_stamm.tarif_speichern",
  egVerteilschluesselSpeichern: "eg_stamm.verteilschluessel_speichern",
  egVerteilschluesselStatus: "eg_stamm.verteilschluessel_status",
  egMassenaktion: "eg_stamm.massenaktion",
  egCsvImport: "eg_stamm.csv_import",
  egCsvExport: "eg_stamm.csv_export",
  egNetzbetreiber: "eg_stamm.netzbetreiber",
  egNetzentgeltRegeln: "eg_stamm.netzentgelt_regeln",
  egVerwaltung: "eg_stamm.verwaltung",
  egMigrationVorschau: "eg_stamm.migration_vorschau",
  egMigrationAusfuehren: "eg_stamm.migration_ausfuehren",
});

export const egKontext = (n, { gemeinschaftId = "" } = {}) => aufruf("egKontext", { gemeinschaftId }, n);
export const egGemeinschaften = (n, filter = {}) => aufruf("egGemeinschaften", { filter }, n);
