  const ziel = e?.operation ? { ...eda, ...abrechnung }[e.operation] : null;
  if (typeof ziel !== "function") return { zugestellt: false };
  try {
    return { zugestellt: true, ergebnis: await ziel(SYSTEM, e.argument ? payload?.[e.argument] : payload) };
  } catch (x) {
