import * as W from "file:///C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/lib/plattform/eg/wechsel.js";
import { NETZBETREIBER } from "file:///C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/lib/plattform/eg/modell.js";
const zp = (i) => `AT0030000000000000000${String(Date.now()).slice(-6)}${String(i).padStart(6, "0")}`;
const csv = `Mitgliedsnummer;Vorname;Nachname;E-Mail;Zählpunktbezeichnung;Energierichtung;Teilnahmefaktor;Tarifgruppe;Teilnehmerstatus\n1;Anna;Test;anna.x@example.com;${zp(1)};Bezug;100;Standard;aktiv\n2;Bert;Test;bert.x@example.com;${zp(2)};Einspeisung;150;Standard;aktiv\n`;
const t = W.tabelleLesen(csv);
const ds = W.zeilenAbbilden(t.zeilen, W.zuordnungVorschlagen(t.kopfNorm));
const p = W.plausibilitaet(ds, { gemeinschaft: { modell: "eeg", netzbetreiber: ["ENB-OOE"] }, netzbetreiber: NETZBETREIBER || [] });
console.log(JSON.stringify(p.fehler), JSON.stringify(p.warnungen).slice(0, 400), W.anbieterErkennen(t.kopfNorm));
const plan = W.importPlan(ds, { bestand: [], ausschliessen: [...new Set(p.fehler.map((f) => f.zeile).filter(Boolean))] });
console.log(plan.zeilen, plan.mitglieder.map((m) => m.mitgliedsnummer + ":" + m.status), plan.csv.split("\n")[0]);

